{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Vol Desk Data",
    "url": "http://localhost:7801",
    "widgets_json": {
      "vix_advanced": {
        "name": "VIX Advanced Chart",
        "description": "TradingView advanced charting for VIX futures.",
        "endpoint": "/udf",
        "type": "advanced_charting",
        "gridData": {
          "w": 20,
          "h": 20
        },
        "staleTime": 900000,
        "params": [
          {
            "paramName": "symbol",
            "type": "text",
            "label": "Symbol",
            "value": "VX1",
            "description": "Advanced chart symbol."
          }
        ],
        "data": {
          "defaultSymbol": "VIX",
          "updateFrequency": 60000
        }
      },
      "vol_regime_metric": {
        "name": "Vol Regime",
        "description": "Current volatility regime score.",
        "endpoint": "/vol-regime",
        "type": "metric",
        "gridData": {
          "w": 6,
          "h": 4
        },
        "staleTime": 900000
      },
      "vix_history": {
        "name": "VIX History",
        "description": "Daily CBOE VIX closes with returns.",
        "endpoint": "/vix-history",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "staleTime": 900000,
        "params": [
          {
            "paramName": "window",
            "type": "number",
            "label": "Window",
            "value": 30,
            "min": 5,
            "max": 365
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "date",
                "headerName": "Date",
                "cellDataType": "dateString"
              },
              {
                "field": "close",
                "headerName": "Close",
                "cellDataType": "number"
              },
              {
                "field": "return_pct",
                "headerName": "Return %",
                "cellDataType": "number",
                "formatterFn": "percent",
                "renderFn": "greenRed"
              }
            ]
          }
        }
      }
    },
    "apps_json": [
      {
        "name": "Vol Advanced Live",
        "description": "VIX TradingView chart and regime.",
        "tabs": {
          "vol": {
            "id": "vol",
            "name": "Vol",
            "layout": [
              {
                "i": "vix_advanced",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 20
              }
            ]
          },
          "signals": {
            "id": "signals",
            "name": "Signals",
            "layout": [
              {
                "i": "vol_regime_metric",
                "x": 20,
                "y": 0,
                "w": 8,
                "h": 5
              }
            ]
          }
        }
      }
    ]
  }
}

{
  "done": false,
  "tool": "manage_apps",
  "args": {
    "operation": "instantiate",
    "backend_id": "backend_001",
    "app_name": "Vol Advanced Live",
    "dashboard_name": "Vol Advanced Live Dashboard"
  }
}

{
  "done": false,
  "tool": "add_generative_widget",
  "args": {
    "dashboard_id": "dash_002",
    "inner_tab": "vol",
    "name": "Vol Advanced Live",
    "widget_type": "note",
    "data": "Vol Advanced Live is live from Vol Desk Data: advanced chart ready."
  }
}
